namespace AutoService.Models; public class JobOrder{ public int Id{get;set;} public int VehicleId{get;set;} public Vehicle? Vehicle{get;set;} public string Title{get;set;} = ""; public JobStatus Status{get;set;} = JobStatus.Planned; public string? Notes{get;set;} public DateTime CreatedAt{get;set;} = DateTime.UtcNow; public DateTime? CompletedAt{get;set;} public decimal LaborHours{get;set;} = 0m; public decimal LaborRate{get;set;} = 0m; public ICollection<JobPart> Parts{get;set;} = new List<JobPart>(); public decimal PartsTotal => Parts.Sum(p => p.LineTotal); public decimal LaborTotal => LaborHours * LaborRate; public decimal Total => PartsTotal + LaborTotal; }